    except Exception as ex:
        r=dict(Z=Z,el=G.GROUND[Z][0],error=str(ex),hitB=False)
    open("testE.jsonl","a").write(json.dumps(r)+"\n")
    print(Z,r["el"],r.get("obs"),r.get("B"),"✓" if r["hitB"] else "✗",flush=True)
